/* UptimeFixer Safe Changes Manager - compact footer v1.2 */
.ufx-safe-footer,
.ufx-safe-footer * { box-sizing: border-box; }

.ufx-safe-footer {
  position: relative;
  width: 100%;
  overflow: hidden;
  background: #10202d;
  color: #f7fbff;
  font-family: inherit;
  border-top: 1px solid rgba(255,255,255,.07);
}

.ufx-safe-footer::before {
  content: "";
  position: absolute;
  inset: 0 0 auto 0;
  height: 3px;
  background: #c8f15a;
}

.ufx-safe-footer__inner {
  width: min(1320px, calc(100% - 56px));
  margin: 0 auto;
  padding: 46px 0 18px;
}

.ufx-safe-footer__top {
  display: grid;
  grid-template-columns: minmax(250px,1.05fr) minmax(320px,1.25fr) minmax(170px,.75fr) minmax(170px,.75fr);
  gap: 52px;
  align-items: start;
}

.ufx-safe-footer__brand {
  max-width: 330px;
}

.ufx-safe-footer__logo {
  display: inline-flex;
  align-items: center;
  margin: 0 0 20px;
  text-decoration: none !important;
}

.ufx-safe-footer__logo img,
.ufx-safe-footer__logo .custom-logo {
  display: block;
  width: auto;
  max-width: 205px;
  max-height: 58px;
  height: auto;
  object-fit: contain;
  background: #fff;
  padding: 7px 11px;
  border-radius: 10px;
  border: 1px solid rgba(255,255,255,.12);
  box-shadow: 0 8px 22px rgba(0,0,0,.12);
}

.ufx-safe-footer__logo .custom-logo-link {
  display: inline-flex;
}

.ufx-safe-footer__logo-text {
  color: #fff;
  font-size: 22px;
  font-weight: 700;
}

.ufx-safe-footer__eyebrow {
  margin: 0 0 8px;
  color: #c8f15a;
  font-size: 11px;
  line-height: 1.2;
  font-weight: 700;
  letter-spacing: .15em;
}

.ufx-safe-footer__brand h2 {
  margin: 0;
  color: #fff;
  font-size: 34px;
  line-height: 1.06;
  letter-spacing: -.035em;
  font-weight: 700;
}

.ufx-safe-footer__brand h2 span {
  color: #dafa86;
}

.ufx-safe-footer__intro {
  max-width: 320px;
  margin: 14px 0 0;
  color: rgba(239,245,250,.70);
  font-size: 14px;
  line-height: 1.65;
}

.ufx-safe-footer__cta {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  min-height: 40px;
  margin-top: 18px;
  padding: 9px 15px;
  border: 1px solid #c8f15a;
  border-radius: 999px;
  background: #c8f15a;
  color: #10202d !important;
  text-decoration: none !important;
  font-size: 13px;
  line-height: 1;
  font-weight: 700;
  transition: transform .18s ease, background .18s ease;
}

.ufx-safe-footer__cta:hover {
  transform: translateY(-1px);
  background: #ddff86;
}

.ufx-safe-footer__cta-label {
  display: inline-flex;
  align-items: center;
}

.ufx-safe-footer__cta-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  flex: 0 0 18px;
  color: #126bff;
  line-height: 1;
  transform: translateY(-1px);
  transition: transform .18s ease, color .18s ease;
}

.ufx-safe-footer__cta-icon svg {
  display: block;
  width: 18px;
  height: 18px;
  overflow: visible;
}

.ufx-safe-footer__cta-icon svg path {
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.ufx-safe-footer__cta:hover .ufx-safe-footer__cta-icon {
  transform: translate(2px,-3px);
  color: #0d5fe8;
}

.ufx-safe-footer__nav-section {
  min-width: 0;
}

.ufx-safe-footer__nav-section h3 {
  margin: 6px 0 18px;
  color: #fff;
  font-size: 12px;
  line-height: 1.2;
  font-weight: 700;
  letter-spacing: .13em;
  text-transform: uppercase;
}

.ufx-safe-footer__nav-section ul {
  list-style: none;
  margin: 0;
  padding: 0;
}

.ufx-safe-footer__tools ul {
  display: grid;
  grid-template-columns: 1fr 1fr;
  column-gap: 30px;
}

.ufx-safe-footer__nav-section li {
  margin: 0 0 12px;
}

.ufx-safe-footer__nav-section a {
  display: inline-flex;
  color: rgba(235,242,248,.72);
  text-decoration: none !important;
  font-size: 14px;
  line-height: 1.4;
  transition: color .18s ease, transform .18s ease;
}

.ufx-safe-footer__nav-section a:hover {
  color: #c8f15a;
  transform: translateX(2px);
}

.ufx-safe-footer__bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 20px;
  margin-top: 28px;
  padding-top: 16px;
  border-top: 1px solid rgba(255,255,255,.10);
}

.ufx-safe-footer__bottom p {
  margin: 0;
  color: rgba(231,239,246,.58);
  font-size: 12px;
  line-height: 1.45;
}

.ufx-safe-footer__bottom a {
  color: #79aaff;
  text-decoration: none !important;
  font-weight: 600;
}

.ufx-safe-footer__bottom a:hover {
  color: #c8f15a;
}

.ufx-safe-footer__heart {
  color: #ff6570;
}

@media (max-width: 1080px) {
  .ufx-safe-footer__inner {
    width: min(100% - 44px,1320px);
    padding-top: 42px;
  }

  .ufx-safe-footer__top {
    grid-template-columns: 1fr 1.15fr 1fr;
    gap: 36px;
  }

  .ufx-safe-footer__brand {
    grid-column: 1 / -1;
    max-width: 600px;
  }

  .ufx-safe-footer__tools ul {
    column-gap: 24px;
  }
}

@media (max-width: 720px) {
  .ufx-safe-footer__inner {
    width: min(100% - 32px,1320px);
    padding: 38px 0 18px;
  }

  .ufx-safe-footer__top {
    grid-template-columns: 1fr 1fr;
    gap: 32px 24px;
  }

  .ufx-safe-footer__brand {
    grid-column: 1 / -1;
  }

  .ufx-safe-footer__tools {
    grid-column: 1 / -1;
  }

  .ufx-safe-footer__brand h2 {
    font-size: 31px;
  }

  .ufx-safe-footer__logo img,
  .ufx-safe-footer__logo .custom-logo {
    max-width: 190px;
  }

  .ufx-safe-footer__bottom {
    flex-direction: column;
    align-items: flex-start;
    gap: 7px;
    margin-top: 28px;
  }
}

@media (max-width: 460px) {
  .ufx-safe-footer__inner {
    width: min(100% - 28px,1320px);
  }

  .ufx-safe-footer__top {
    grid-template-columns: 1fr;
  }

  .ufx-safe-footer__brand,
  .ufx-safe-footer__tools {
    grid-column: auto;
  }

  .ufx-safe-footer__tools ul {
    grid-template-columns: 1fr 1fr;
    column-gap: 20px;
  }

  .ufx-safe-footer__brand h2 {
    font-size: 29px;
  }

  .ufx-safe-footer__cta {
    width: auto;
  }
}

/* UFX HOMEPAGE V2 START */
/* TinyWow-inspired, original UptimeFixer homepage: spacious, utility-first, ad-friendly */
body.ufx-studio {
  background: #ffffff;
  color: #132333;
}

body.ufx-studio .site-main {
  overflow: hidden;
}

body.ufx-studio .studio-topline {
  width: min(1180px, calc(100% - 40px));
  min-height: 42px;
  margin: 18px auto 0;
  padding: 0 2px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  color: #66727e;
  font-size: 13px;
  line-height: 1.4;
}

body.ufx-studio .studio-topline > span:first-child {
  display: inline-flex;
  align-items: center;
  gap: 9px;
}

body.ufx-studio .studio-topline > span:first-child i {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #b9ee54;
  box-shadow: 0 0 0 5px rgba(185,238,84,.16);
}

body.ufx-studio .studio-hero {
  width: min(1180px, calc(100% - 40px));
  margin: 12px auto 0;
  min-height: 520px;
  padding: 68px 70px;
  display: grid;
  grid-template-columns: minmax(0,1.35fr) minmax(320px,.65fr);
  gap: 44px;
  align-items: center;
  position: relative;
  border: 1px solid #e6ebef;
  border-radius: 30px;
  background:
    radial-gradient(circle at 82% 18%, rgba(199,242,92,.32), transparent 28%),
    radial-gradient(circle at 92% 76%, rgba(30,111,255,.12), transparent 30%),
    linear-gradient(135deg,#f8fbfd 0%,#ffffff 56%,#f6fbff 100%);
  box-shadow: 0 28px 80px rgba(15,31,44,.07);
}

body.ufx-studio .studio-hero-copy {
  max-width: 720px;
  position: relative;
  z-index: 2;
}

body.ufx-studio .studio-eyebrow {
  color: #4e6476;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: .14em;
}

body.ufx-studio .studio-hero h1 {
  margin: 14px 0 20px;
  max-width: 780px;
  color: #10202d;
  font-size: clamp(48px,5.2vw,72px);
  line-height: .98;
  letter-spacing: -.055em;
  font-weight: 750;
}

body.ufx-studio .studio-hero h1 span {
  color: #126bff;
}

body.ufx-studio .studio-intro {
  max-width: 680px;
  margin: 0;
  color: #62707d;
  font-size: 18px;
  line-height: 1.65;
}

body.ufx-studio .studio-search {
  max-width: 720px;
  min-height: 64px;
  margin-top: 30px;
  padding: 8px 10px 8px 20px;
  display: grid;
  grid-template-columns: auto minmax(0,1fr) auto;
  gap: 12px;
  align-items: center;
  position: relative;
  background: #fff;
  border: 1px solid #dce4ea;
  border-radius: 18px;
  box-shadow: 0 14px 38px rgba(15,31,44,.09);
}

body.ufx-studio .studio-search:focus-within {
  border-color: #126bff;
  box-shadow: 0 0 0 4px rgba(18,107,255,.08),0 14px 38px rgba(15,31,44,.09);
}

body.ufx-studio .studio-search input[type="search"] {
  width: 100%;
  min-width: 0;
  height: 46px;
  padding: 0;
  border: 0;
  outline: 0;
  box-shadow: none;
  background: transparent;
  color: #10202d;
  font: inherit;
  font-size: 16px;
}

body.ufx-studio .studio-search button {
  width: 46px;
  height: 46px;
  padding: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: 13px;
  background: #126bff;
  color: #fff;
  cursor: pointer;
  transition: transform .18s ease, background .18s ease;
}

body.ufx-studio .studio-search button:hover {
  transform: translateY(-1px);
  background: #005cf0;
}

body.ufx-studio .ufx-home-search-results {
  top: calc(100% + 10px);
  border-radius: 16px;
  border: 1px solid #e0e7ec;
  box-shadow: 0 24px 50px rgba(15,31,44,.13);
}

body.ufx-studio .studio-promises {
  margin-top: 20px;
  display: flex;
  flex-wrap: wrap;
  gap: 10px 18px;
}

body.ufx-studio .studio-promises span {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: #52616f;
  font-size: 13px;
  font-weight: 600;
}

body.ufx-studio .studio-hero-art {
  min-height: 330px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}

body.ufx-studio .studio-hero-art img {
  width: min(100%,420px);
  height: auto;
  object-fit: contain;
  filter: drop-shadow(0 22px 30px rgba(15,31,44,.13));
  transform: rotate(1deg);
}

body.ufx-studio .studio-art-note {
  right: 2px;
  bottom: 10px;
  padding: 10px 14px;
  border: 1px solid rgba(15,31,44,.08);
  border-radius: 12px;
  background: rgba(255,255,255,.88);
  color: #203140;
  box-shadow: 0 10px 28px rgba(15,31,44,.08);
  backdrop-filter: blur(8px);
  font-size: 13px;
}

body.ufx-studio .studio-quick {
  width: min(1120px, calc(100% - 40px));
  margin: 28px auto 0;
  padding: 16px 18px;
  display: grid;
  grid-template-columns: 1.1fr repeat(5,1fr);
  gap: 10px;
  align-items: stretch;
  border: 1px solid #e6ebef;
  border-radius: 18px;
  background: #fff;
  box-shadow: 0 12px 34px rgba(15,31,44,.05);
}

body.ufx-studio .studio-quick > div:first-child {
  padding: 10px 12px;
}

body.ufx-studio .studio-quick h2 {
  margin: 0 0 3px;
  color: #10202d;
  font-size: 18px;
  letter-spacing: -.02em;
}

body.ufx-studio .studio-quick p {
  margin: 0;
  color: #84909a;
  font-size: 12px;
}

body.ufx-studio .studio-quick > a {
  min-height: 70px;
  padding: 12px 12px;
  display: flex;
  align-items: center;
  gap: 9px;
  border: 1px solid transparent;
  border-radius: 13px;
  background: #f7f9fb;
  color: #203140;
  text-decoration: none;
  transition: transform .18s ease,border-color .18s ease,background .18s ease;
}

body.ufx-studio .studio-quick > a:hover {
  transform: translateY(-2px);
  border-color: #dbe5ec;
  background: #fff;
}

body.ufx-studio .studio-quick > a > span:first-child,
body.ufx-studio .studio-quick > a > svg {
  flex: 0 0 auto;
}

body.ufx-studio .studio-quick strong {
  min-width: 0;
  font-size: 13px;
  line-height: 1.3;
}

body.ufx-studio .studio-section {
  width: min(1180px, calc(100% - 40px));
  margin-left: auto;
  margin-right: auto;
  padding-top: 92px;
  padding-bottom: 0;
}

body.ufx-studio .studio-heading {
  margin-bottom: 30px;
  align-items: end;
}

body.ufx-studio .studio-heading h2 {
  margin: 7px 0 0;
  color: #10202d;
  font-size: clamp(32px,3.3vw,46px);
  line-height: 1.05;
  letter-spacing: -.04em;
}

body.ufx-studio .studio-heading > p {
  max-width: 420px;
  color: #6d7a86;
  font-size: 15px;
  line-height: 1.6;
}

body.ufx-studio .studio-text-link {
  color: #126bff;
  font-size: 14px;
  font-weight: 700;
}

body.ufx-studio .studio-collections {
  display: grid;
  grid-template-columns: repeat(3,minmax(0,1fr));
  gap: 18px;
}

body.ufx-studio .studio-collection {
  min-height: 235px;
  padding: 24px;
  position: relative;
  overflow: hidden;
  border: 1px solid #e2e8ed;
  border-radius: 20px;
  background: #f8fafb;
  box-shadow: none;
  transition: transform .2s ease,border-color .2s ease,box-shadow .2s ease;
}

body.ufx-studio .studio-collection:hover {
  transform: translateY(-4px);
  border-color: #d3dde5;
  box-shadow: 0 18px 36px rgba(15,31,44,.08);
}

body.ufx-studio .studio-collection-copy {
  max-width: 70%;
  position: relative;
  z-index: 2;
}

body.ufx-studio .studio-card-number {
  color: #71808c;
  font-size: 11px;
  letter-spacing: .09em;
  text-transform: uppercase;
}

body.ufx-studio .studio-collection h3 {
  margin: 16px 0 8px;
  color: #10202d;
  font-size: 24px;
  line-height: 1.05;
  letter-spacing: -.03em;
}

body.ufx-studio .studio-collection p {
  color: #65727e;
  font-size: 14px;
  line-height: 1.55;
}

body.ufx-studio .studio-collection img {
  width: 118px;
  height: 118px;
  right: 13px;
  bottom: 40px;
  object-fit: contain;
  opacity: .96;
}

body.ufx-studio .studio-card-bottom {
  left: 24px;
  right: 24px;
  bottom: 17px;
  color: #40515f;
  font-size: 12px;
  font-weight: 700;
}

body.ufx-studio .studio-more {
  margin-top: 18px;
  padding: 0;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  color: #7c8994;
  font-size: 13px;
}

body.ufx-studio .studio-more > span {
  padding: 9px 0;
}

body.ufx-studio .studio-more a {
  padding: 8px 12px;
  border: 1px solid #e2e8ed;
  border-radius: 999px;
  background: #fff;
  color: #3a4b59;
  text-decoration: none;
  transition: border-color .18s ease,color .18s ease;
}

body.ufx-studio .studio-more a:hover {
  border-color: #126bff;
  color: #126bff;
}

body.ufx-studio .studio-directory {
  padding-top: 92px;
}

body.ufx-studio .studio-shortlist {
  display: grid;
  grid-template-columns: repeat(4,minmax(0,1fr));
  gap: 14px;
}

body.ufx-studio .studio-shortlist > a {
  min-height: 160px;
  padding: 22px;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  position: relative;
  border: 1px solid #e4eaee;
  border-radius: 18px;
  background: #fff;
  text-decoration: none;
  box-shadow: 0 9px 26px rgba(15,31,44,.045);
  transition: transform .2s ease,border-color .2s ease,box-shadow .2s ease;
}

body.ufx-studio .studio-shortlist > a:hover {
  transform: translateY(-3px);
  border-color: #cfdbe3;
  box-shadow: 0 18px 34px rgba(15,31,44,.08);
}

body.ufx-studio .studio-short-icon {
  width: 42px;
  height: 42px;
  margin-bottom: 18px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 12px;
  background: #eef5ff;
  color: #126bff;
}

body.ufx-studio .studio-shortlist h3 {
  margin: 0 0 8px;
  color: #152735;
  font-size: 16px;
  line-height: 1.25;
}

body.ufx-studio .studio-shortlist p {
  margin: 0;
  color: #73808b;
  font-size: 13px;
  line-height: 1.55;
}

body.ufx-studio .studio-shortlist > a > span:last-child {
  position: absolute;
  top: 22px;
  right: 20px;
  color: #126bff;
}

body.ufx-studio .studio-button {
  margin: 22px auto 0;
  max-width: 320px;
  min-height: 48px;
  border-radius: 999px;
  background: #10202d;
  color: #fff;
  box-shadow: none;
}

body.ufx-studio .studio-button:hover {
  background: #126bff;
}

body.ufx-studio #guides {
  margin-top: 92px;
  padding: 58px;
  border-radius: 26px;
  background: #f6f8fa;
}

body.ufx-studio .studio-guides {
  gap: 18px;
}

body.ufx-studio .studio-guide {
  border: 1px solid #e0e6eb;
  border-radius: 18px;
  background: #fff;
  overflow: hidden;
  box-shadow: none;
}

body.ufx-studio .studio-guide-image {
  height: 180px;
  overflow: hidden;
  background: #edf2f5;
}

body.ufx-studio .studio-guide-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

body.ufx-studio .studio-guide-copy {
  padding: 20px;
}

body.ufx-studio .studio-guide h3 {
  color: #162735;
  font-size: 18px;
  line-height: 1.25;
}

body.ufx-studio .studio-guide p {
  color: #6d7a85;
  font-size: 13px;
  line-height: 1.55;
}

body.ufx-studio .studio-privacy {
  width: min(1180px, calc(100% - 40px));
  margin: 92px auto 0;
  padding: 38px 40px;
  display: grid;
  grid-template-columns: 1.3fr repeat(3,1fr);
  gap: 24px;
  border-radius: 24px;
  background: #10202d;
}

body.ufx-studio .studio-privacy > div:first-child h2 {
  margin: 8px 0 0;
  color: #fff;
  font-size: 34px;
  line-height: 1.05;
  letter-spacing: -.04em;
}

body.ufx-studio .studio-privacy .studio-eyebrow {
  color: #c8f15a;
}

body.ufx-studio .studio-privacy > div:not(:first-child) {
  padding: 4px 0 0 20px;
  border-left: 1px solid rgba(255,255,255,.11);
}

body.ufx-studio .studio-privacy h3 {
  margin: 12px 0 7px;
  color: #fff;
  font-size: 16px;
}

body.ufx-studio .studio-privacy p {
  color: rgba(238,244,249,.65);
  font-size: 13px;
  line-height: 1.55;
}

body.ufx-studio .studio-bottom {
  padding-top: 92px;
  padding-bottom: 84px;
}

body.ufx-studio .studio-note,
body.ufx-studio .studio-faq {
  border: 1px solid #e3e9ee;
  border-radius: 22px;
  background: #fff;
}

body.ufx-studio .studio-note {
  padding: 38px;
}

body.ufx-studio .studio-note h2 {
  margin: 8px 0 14px;
  color: #10202d;
  font-size: 38px;
  line-height: 1.05;
  letter-spacing: -.04em;
}

body.ufx-studio .studio-note p {
  color: #6e7b86;
